mapper.select:
SELECT COUNT(DISTINCT sale_no)
FROM sh7_saleplu
WHERE CAST(xsdate AS DATE) >= #{param.periodStart}
  AND CAST(xsdate AS DATE) <= #{param.periodEnd}

SELECT COUNT(DISTINCT sale_no)
FROM sh7_saleplu
WHERE CAST(xsdate AS DATE) >= #{param.periodStart}
  AND CAST(xsdate AS DATE) <= #{param.periodEnd}

WITH sales_agg AS ( SELECT , ISNULL(SUM(CAST(sales AS DECIMAL(20, 6))), 0) AS totalSales, ISNULL(SUM(CAST(gross AS DECIMAL(20, 6))), 0) AS totalGross, ISNULL(SUM(CAST(sale_quantity AS DECIMAL(20, 6))), 0) AS totalSaleQuantity, ISNULL(SUM(CAST(sale_cost AS DECIMAL(20, 6))), 0) AS totalSaleCost, CAST(COUNT(DISTINCT CASE WHEN sales > 0 THEN product_no ELSE NULL END) AS INT) AS activeSku FROM fact_sales_day
GROUP BY
two_class_no, two_class_name three_class_no, three_class_name four_class_no, four_class_name five_class_no, five_class_name
), customer_agg AS ( SELECT , COUNT(DISTINCT sale_no) AS totalCustomerCount FROM sh7_saleplu WHERE CAST(xsdate AS DATE) >= #{param.periodStart} AND CAST(xsdate AS DATE) <= #{param.periodEnd}
GROUP BY
two_class_no, two_class_name three_class_no, three_class_name four_class_no, four_class_name five_class_no, five_class_name
), inventory_daily AS ( SELECT stock_date, , ISNULL(SUM(CAST(stock_sale_money AS DECIMAL(20, 6))), 0) AS dayStockSaleMoney FROM fact_stock_day WHERE stock_date >= #{param.periodStart} AND stock_date <= #{param.periodEnd}
GROUP BY stock_date,
two_class_no, two_class_name three_class_no, three_class_name four_class_no, four_class_name five_class_no, five_class_name
), inventory_agg AS ( SELECT subClassLevel, subClassNo, MAX(subClassName) AS subClassName, ISNULL(AVG(CAST(dayStockSaleMoney AS DECIMAL(20, 6))), 0) AS avgInventory FROM inventory_daily GROUP BY subClassLevel, subClassNo ), sku_agg AS ( SELECT , CAST(COUNT(DISTINCT p.product_no) AS INT) AS totalSku FROM base_dept_products p WHERE p.product_no IS NOT NULL AND LTRIM(RTRIM(p.product_no)) <> ''
AND ISNULL(LTRIM(RTRIM(p.status_name)), '') NOT IN (N'停用', N'作废', N'下架', N'无效') GROUP BY
p.two_class_no, p.two_class_name p.three_class_no, p.three_class_name p.four_class_no, p.four_class_name p.five_class_no, p.five_class_name
) SELECT s.subClassLevel, s.subClassNo, s.subClassName, s.totalSales, s.totalGross, s.totalSaleQuantity, s.totalSaleCost, ISNULL(c.totalCustomerCount, 0) AS totalCustomerCount, ISNULL(i.avgInventory, 0) AS avgInventory, ISNULL(k.totalSku, 0) AS totalSku, ISNULL(s.activeSku, 0) AS activeSku FROM sales_agg s LEFT JOIN customer_agg c ON c.subClassLevel = s.subClassLevel AND c.subClassNo = s.subClassNo LEFT JOIN inventory_agg i ON i.subClassLevel = s.subClassLevel AND i.subClassNo = s.subClassNo LEFT JOIN sku_agg k ON k.subClassLevel = s.subClassLevel AND k.subClassNo = s.subClassNo ORDER BY s.subClassNo ASC

WITH sales_agg AS ( SELECT sale_channel AS saleChannel, CASE WHEN sale_channel = 1 THEN NULL ELSE NULLIF(LTRIM(RTRIM(online_type)), '') END AS onlineType, MAX(NULLIF(LTRIM(RTRIM(online_name)), '')) AS onlineName, ISNULL(SUM(CAST(sales AS DECIMAL(20, 6))), 0) AS totalSales, ISNULL(SUM(CAST(gross AS DECIMAL(20, 6))), 0) AS totalGross FROM fact_sales_day WHERE sale_date >= #{param.periodStart} AND sale_date <= #{param.periodEnd}
GROUP BY sale_channel, CASE WHEN sale_channel = 1 THEN NULL ELSE NULLIF(LTRIM(RTRIM(online_type)), '') END ), customer_agg AS ( SELECT sale_channel AS saleChannel, CASE WHEN sale_channel = 1 THEN NULL ELSE NULLIF(LTRIM(RTRIM(online_type)), '') END AS onlineType, MAX(NULLIF(LTRIM(RTRIM(online_name)), '')) AS onlineName, COUNT(DISTINCT sale_no) AS totalCustomerCount FROM sh7_saleplu WHERE CAST(xsdate AS DATE) >= #{param.periodStart} AND CAST(xsdate AS DATE) <= #{param.periodEnd}
GROUP BY sale_channel, CASE WHEN sale_channel = 1 THEN NULL ELSE NULLIF(LTRIM(RTRIM(online_type)), '') END ) SELECT COALESCE(s.saleChannel, c.saleChannel) AS saleChannel, COALESCE(s.onlineType, c.onlineType) AS onlineType, COALESCE(s.onlineName, c.onlineName) AS onlineName, ISNULL(s.totalSales, 0) AS totalSales, ISNULL(s.totalGross, 0) AS totalGross, ISNULL(CAST(c.totalCustomerCount AS DECIMAL(20, 2)), 0) AS totalCustomerCount FROM sales_agg s FULL OUTER JOIN customer_agg c ON c.saleChannel = s.saleChannel AND ISNULL(c.onlineType, '') = ISNULL(s.onlineType, '') ORDER BY COALESCE(s.saleChannel, c.saleChannel), COALESCE(s.onlineType, c.onlineType)

WITH brand_dim AS ( SELECT p.product_no AS productNo, MAX(NULLIF(LTRIM(RTRIM(p.product_brand)), '')) AS productBrand FROM base_dept_products p WHERE 1 = 1
GROUP BY p.product_no ), daily_stock AS ( SELECT stock_date, ISNULL(NULLIF(LTRIM(RTRIM(d.productBrand)), ''), N'/') AS brandNo, ISNULL(SUM(CAST(stock_quantity AS DECIMAL(20, 6))), 0) AS dayStockQuantity FROM fact_stock_day LEFT JOIN brand_dim d ON d.productNo = fact_stock_day.product_no WHERE stock_date >= #{param.periodStart} AND stock_date <= #{param.periodEnd}
GROUP BY stock_date, ISNULL(NULLIF(LTRIM(RTRIM(d.productBrand)), ''), N'/') ) SELECT brandNo, ISNULL(AVG(CAST(dayStockQuantity AS DECIMAL(20, 6))), 0) AS avgStockQuantity FROM daily_stock GROUP BY brandNo

WITH spec_meta AS ( SELECT p.product_no AS productNo, ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') AS specNo, ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') AS specName, CASE WHEN ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') = N'/' THEN N'/' ELSE N'1' END AS specType, CASE WHEN ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') = N'/' THEN N'无规格' ELSE N'其他规格' END AS specTypeName FROM base_dept_products p WHERE 1 = 1
GROUP BY p.product_no, ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') ), sales_base AS ( SELECT m.specNo AS specNo, MAX(m.specName) AS specName, MAX(m.specType) AS specType, MAX(m.specTypeName) AS specTypeName, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.product_no ELSE NULL END) AS skuCount, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.store_no ELSE NULL END) AS activeStoreCount, ISNULL(SUM(CAST(s.sale_quantity AS DECIMAL(20, 6))), 0) AS saleQuantity, ISNULL(SUM(CAST(s.sales AS DECIMAL(20, 6))), 0) AS sales, ISNULL(SUM(CAST(s.gross AS DECIMAL(20, 6))), 0) AS gross, ISNULL(SUM(CAST(s.sale_cost AS DECIMAL(20, 6))), 0) AS saleCost, COUNT(DISTINCT CASE WHEN ISNULL(LTRIM(RTRIM(s.cx_flag)), '0') IN ('1', 'Y', 'y', 'true', 'TRUE') THEN s.product_no ELSE NULL END) AS activitySku FROM fact_sales_day s INNER JOIN spec_meta m ON m.productNo = s.product_no WHERE s.sale_date >= #{param.periodStart} AND s.sale_date <= #{param.periodEnd}
GROUP BY m.specNo ) SELECT specNo, specName, specType, specTypeName, CAST(ISNULL(skuCount, 0) AS INT) AS skuCount, CAST(ISNULL(activeStoreCount, 0) AS INT) AS activeStoreCount, ISNULL(saleQuantity, 0) AS saleQuantity, ISNULL(sales, 0) AS sales, ISNULL(gross, 0) AS gross, ISNULL(saleCost, 0) AS saleCost, CAST(ISNULL(activitySku, 0) AS INT) AS activitySku FROM sales_base ORDER BY sales DESC, specNo ASC

WITH spec_meta AS ( SELECT p.product_no AS productNo, ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') AS specNo FROM base_dept_products p WHERE 1 = 1
GROUP BY p.product_no, ISNULL(NULLIF(LTRIM(RTRIM(p.product_spec)), ''), N'/') ), daily_stock AS ( SELECT s.stock_date AS stockDate, m.specNo AS specNo, ISNULL(SUM(CAST(s.stock_quantity AS DECIMAL(20, 6))), 0) AS dayStockQuantity FROM fact_stock_day s INNER JOIN spec_meta m ON m.productNo = s.product_no WHERE s.stock_date >= #{param.periodStart} AND s.stock_date <= #{param.periodEnd}
GROUP BY s.stock_date, m.specNo ) SELECT specNo, ISNULL(AVG(CAST(dayStockQuantity AS DECIMAL(20, 6))), 0) AS avgStockQuantity FROM daily_stock GROUP BY specNo

WITH product_scope AS ( SELECT DISTINCT p.product_no AS productNo FROM base_dept_products p WHERE 1 = 1
), tag_scope AS ( SELECT t.product_no AS productNo, t.tag_type_no AS tagType, MAX(t.tag_type_name) AS tagTypeName, t.tag_no AS tagNo, MAX(t.tag_name) AS tagName, CONCAT(t.tag_type_no, N'|', t.tag_no) AS metricKey, CAST(0 AS BIT) AS isUntagged FROM product_tag_info t INNER JOIN product_scope p ON p.productNo = t.product_no GROUP BY t.product_no, t.tag_type_no, t.tag_no ), tag_sales AS ( SELECT ts.tagType, MAX(ts.tagTypeName) AS tagTypeName, ts.tagNo, MAX(ts.tagName) AS tagName, ts.metricKey, CAST(0 AS BIT) AS isUntagged, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.product_no ELSE NULL END) AS skuCount, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.store_no ELSE NULL END) AS activeStoreCount, ISNULL(SUM(CAST(s.sale_quantity AS DECIMAL(20, 6))), 0) AS saleQuantity, ISNULL(SUM(CAST(s.sales AS DECIMAL(20, 6))), 0) AS sales, ISNULL(SUM(CAST(s.gross AS DECIMAL(20, 6))), 0) AS gross, ISNULL(SUM(CAST(s.sale_cost AS DECIMAL(20, 6))), 0) AS saleCost, COUNT(DISTINCT CASE WHEN ISNULL(LTRIM(RTRIM(s.cx_flag)), '0') IN ('1', 'Y', 'y', 'true', 'TRUE') THEN s.product_no ELSE NULL END) AS activitySku FROM fact_sales_day s INNER JOIN tag_scope ts ON ts.productNo = s.product_no WHERE s.sale_date >= #{param.periodStart} AND s.sale_date <= #{param.periodEnd}
GROUP BY ts.tagType, ts.tagNo, ts.metricKey ), untagged_sales AS ( SELECT N'*' AS tagType, N'无标签' AS tagTypeName, CAST(NULL AS NVARCHAR(128)) AS tagNo, N'无标签' AS tagName, N'__UNTAGGED__' AS metricKey, CAST(1 AS BIT) AS isUntagged, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.product_no ELSE NULL END) AS skuCount, COUNT(DISTINCT CASE WHEN s.sales > 0 THEN s.store_no ELSE NULL END) AS activeStoreCount, ISNULL(SUM(CAST(s.sale_quantity AS DECIMAL(20, 6))), 0) AS saleQuantity, ISNULL(SUM(CAST(s.sales AS DECIMAL(20, 6))), 0) AS sales, ISNULL(SUM(CAST(s.gross AS DECIMAL(20, 6))), 0) AS gross, ISNULL(SUM(CAST(s.sale_cost AS DECIMAL(20, 6))), 0) AS saleCost, COUNT(DISTINCT CASE WHEN ISNULL(LTRIM(RTRIM(s.cx_flag)), '0') IN ('1', 'Y', 'y', 'true', 'TRUE') THEN s.product_no ELSE NULL END) AS activitySku FROM fact_sales_day s INNER JOIN product_scope p ON p.productNo = s.product_no WHERE s.sale_date >= #{param.periodStart} AND s.sale_date <= #{param.periodEnd}
AND NOT EXISTS ( SELECT 1 FROM product_tag_info t WHERE t.product_no = s.product_no ) ) SELECT tagType, tagTypeName, tagNo, tagName, metricKey, isUntagged, CAST(ISNULL(skuCount, 0) AS INT) AS skuCount, CAST(ISNULL(activeStoreCount, 0) AS INT) AS activeStoreCount, ISNULL(saleQuantity, 0) AS saleQuantity, ISNULL(sales, 0) AS sales, ISNULL(gross, 0) AS gross, ISNULL(saleCost, 0) AS saleCost, CAST(ISNULL(activitySku, 0) AS INT) AS activitySku FROM ( SELECT * FROM tag_sales UNION ALL SELECT * FROM untagged_sales ) x ORDER BY sales DESC, metricKey ASC

WITH product_scope AS ( SELECT DISTINCT p.product_no AS productNo FROM base_dept_products p WHERE 1 = 1
), tag_scope AS ( SELECT t.product_no AS productNo, CONCAT(t.tag_type_no, N'|', t.tag_no) AS metricKey FROM product_tag_info t INNER JOIN product_scope p ON p.productNo = t.product_no GROUP BY t.product_no, t.tag_type_no, t.tag_no ), tag_daily_stock AS ( SELECT s.stock_date AS stockDate, ts.metricKey AS metricKey, ISNULL(SUM(CAST(s.stock_quantity AS DECIMAL(20, 6))), 0) AS dayStockQuantity FROM fact_stock_day s INNER JOIN tag_scope ts ON ts.productNo = s.product_no WHERE s.stock_date >= #{param.periodStart} AND s.stock_date <= #{param.periodEnd}
GROUP BY s.stock_date, ts.metricKey ), untagged_daily_stock AS ( SELECT s.stock_date AS stockDate, N'__UNTAGGED__' AS metricKey, ISNULL(SUM(CAST(s.stock_quantity AS DECIMAL(20, 6))), 0) AS dayStockQuantity FROM fact_stock_day s INNER JOIN product_scope p ON p.productNo = s.product_no WHERE s.stock_date >= #{param.periodStart} AND s.stock_date <= #{param.periodEnd}
AND NOT EXISTS ( SELECT 1 FROM product_tag_info t WHERE t.product_no = s.product_no ) GROUP BY s.stock_date ) SELECT metricKey, ISNULL(AVG(CAST(dayStockQuantity AS DECIMAL(20, 6))), 0) AS avgStockQuantity FROM ( SELECT * FROM tag_daily_stock UNION ALL SELECT * FROM untagged_daily_stock ) x GROUP BY metricKey

WITH scoped_products AS ( SELECT DISTINCT v.vendor_no AS vendorNo, MAX(v.vendor_name) AS vendorName, MAX(v.status_no) AS statusNo, MAX(v.status_name) AS statusName, p.product_no AS productNo, p.store_no AS storeNo, MAX(CAST(ISNULL(p.product_taxin_inprice, 0) AS DECIMAL(20, 6))) AS inPrice, MIN(CAST(p.first_order_date AS DATE)) AS firstOrderDate FROM base_dept_products p INNER JOIN base_vendor_product_info v ON v.product_no = p.product_no WHERE 1 = 1
GROUP BY v.vendor_no, p.product_no, p.store_no ), vendor_scope AS ( SELECT vendorNo, MAX(vendorName) AS vendorName, MAX(statusNo) AS statusNo, MAX(statusName) AS statusName, COUNT(DISTINCT productNo) AS skuCount, COUNT(DISTINCT CASE WHEN firstOrderDate IS NOT NULL AND firstOrderDate >= #{param.periodStart} AND firstOrderDate <= #{param.periodEnd} THEN productNo ELSE NULL END) AS newSkuCount FROM scoped_products GROUP BY vendorNo ), sales_agg AS ( SELECT sp.vendorNo AS vendorNo, ISNULL(SUM(CAST(fact_sales_day.sales AS DECIMAL(20, 6))), 0) AS sales, ISNULL(SUM(CAST(fact_sales_day.gross AS DECIMAL(20, 6))), 0) AS gross FROM fact_sales_day INNER JOIN ( SELECT DISTINCT vendorNo, productNo FROM scoped_products ) sp ON sp.productNo = fact_sales_day.product_no WHERE fact_sales_day.sale_date >= #{param.periodStart} AND fact_sales_day.sale_date <= #{param.periodEnd}
GROUP BY sp.vendorNo ), order_agg AS ( SELECT sp.vendorNo AS vendorNo, ISNULL(SUM(CAST(ISNULL(vo.arrival_quantity, 0) * ISNULL(sp.inPrice, 0) AS DECIMAL(20, 6))), 0) AS netOrderAmount, ISNULL(SUM(CAST(CASE WHEN ISNULL(vo.order_quantity, 0) > ISNULL(vo.arrival_quantity, 0) THEN (ISNULL(vo.order_quantity, 0) - ISNULL(vo.arrival_quantity, 0)) * ISNULL(sp.inPrice, 0) ELSE 0 END AS DECIMAL(20, 6))), 0) AS diffOrderAmount, ISNULL(SUM(CAST(ISNULL(vo.order_quantity, 0) * ISNULL(sp.inPrice, 0) AS DECIMAL(20, 6))), 0) AS baseOrderAmount FROM fact_vendor_order_month vo INNER JOIN ( SELECT DISTINCT vendorNo, productNo, storeNo, inPrice FROM scoped_products ) sp ON sp.vendorNo = vo.vendor_no AND sp.productNo = vo.product_no AND sp.storeNo = vo.final_store_no WHERE vo.order_date >= #{param.periodStart} AND vo.order_date <= #{param.periodEnd} GROUP BY sp.vendorNo ), cost_agg AS ( SELECT sp.vendorNo AS vendorNo, ISNULL(SUM(CAST(pvc.cost_money AS DECIMAL(20, 6))), 0) AS oiAmount FROM product_vendor_cost_info pvc INNER JOIN ( SELECT DISTINCT vendorNo, productNo, storeNo FROM scoped_products ) sp ON sp.vendorNo = pvc.vendor_no AND sp.productNo = pvc.product_no AND sp.storeNo = pvc.final_store_no WHERE pvc.cost_date >= #{param.periodStart} AND pvc.cost_date <= #{param.periodEnd} GROUP BY sp.vendorNo ) SELECT vs.vendorNo, vs.vendorName, vs.statusNo, vs.statusName, CAST(ISNULL(vs.skuCount, 0) AS INT) AS skuCount, CAST(ISNULL(vs.newSkuCount, 0) AS INT) AS newSkuCount, ISNULL(sa.sales, 0) AS sales, ISNULL(sa.gross, 0) AS gross, ISNULL(ca.oiAmount, 0) AS oiAmount, ISNULL(oa.netOrderAmount, 0) AS netOrderAmount, ISNULL(oa.diffOrderAmount, 0) AS diffOrderAmount, ISNULL(oa.baseOrderAmount, 0) AS baseOrderAmount FROM vendor_scope vs LEFT JOIN sales_agg sa ON sa.vendorNo = vs.vendorNo LEFT JOIN order_agg oa ON oa.vendorNo = vs.vendorNo LEFT JOIN cost_agg ca ON ca.vendorNo = vs.vendorNo ORDER BY ISNULL(sa.sales, 0) DESC, vs.vendorNo ASC

SELECT d.dict_code AS dictCode, t.dict_id AS dictId, d.dict_sort AS dictSort, d.dict_label AS dictLabel, d.dict_value AS dictValue, CONVERT(VARCHAR(19), d.create_time, 120) AS createTime FROM sys_dict_data d LEFT JOIN sys_dict_type t ON t.dict_type = d.dict_type AND t.tenant_id = d.tenant_id WHERE d.tenant_id = N'000000' AND d.dict_type IN
#{dictType}
ORDER BY d.dict_type ASC, d.dict_sort ASC, d.dict_code ASC
